let current = 'en';
export const LANGUAGES = { en: 'English', zh: '中文' };
export function setLang(lang) { current = STRINGS[lang] ? lang : 'en'; return current; }
export function getLang() { return current; }
export function t(key, vars = {}) {
  const text = STRINGS[current][key] ?? STRINGS.en[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? '');
}
export function name(zh) { return current === 'en' ? NAMES_EN[zh] ?? zh : zh; }
